#if canImport(UIKit)
import UIKit

/// Every state of the call screen with no call: calling,
/// ringing, connecting, a call by voice and by video, the microphone and camera off, the other side lost, this side
/// reconnecting, and a group call by video and by voice, each in light and dark and right to left. The app's pieces
/// (`CallScreen.shared.pieces`) and look (`configure`) are drawn as in a call, and an app that copied the screen
/// (`swift package wordplus-ui add`) has this file in its copy, so the preview draws the copy.
///
///     window.rootViewController = UINavigationController( rootViewController: CallScreenPreview() )
///
/// lists the states; `CallScreenPreview( .video )` shows one, as Xcode's canvas does:
/// `#Preview { CallScreenPreview( .video ) }`.
@MainActor
public final class CallScreenPreview: UIViewController, UITableViewDataSource, UITableViewDelegate {
    /// A state the screen can be in.
    public enum Shown: String, CaseIterable, Sendable {
        case calling, ringing, connecting, voice, video, off, peerLost, reconnecting, group, groupVoice

        public var title: String {
            switch self {
            case .calling: return "Calling"
            case .ringing: return "Ringing in"
            case .connecting: return "Connecting"
            case .voice: return "In a call by voice"
            case .video: return "In a call by video"
            case .off: return "Microphone and camera off"
            case .peerLost: return "The other side lost"
            case .reconnecting: return "This side reconnecting"
            case .group: return "Group call by video"
            case .groupVoice: return "Group call by voice"
            }
        }
    }

    private let shown: Shown?
    private var dark = false
    private var rightToLeft = false
    private var screen: BmCallsScreen?

    /// The list of states, or one state alone.
    public init( _ shown: Shown? = nil ) {
        self.shown = shown
        super.init( nibName: nil, bundle: nil )
    }

    @available( *, unavailable )
    required init?( coder: NSCoder ) { fatalError( "init(coder:) is not supported" ) }

    public override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = .systemBackground

        guard let shown else {
            title = "Call screen"
            let list = UITableView( frame: view.bounds, style: .insetGrouped )
            list.autoresizingMask = [ .flexibleWidth, .flexibleHeight ]
            list.dataSource = self
            list.delegate = self
            list.register( UITableViewCell.self, forCellReuseIdentifier: "state" )
            view.addSubview( list )
            return
        }

        title = shown.title
        navigationItem.rightBarButtonItems = [
            UIBarButtonItem( title: "Dark", style: .plain, target: self, action: #selector( toggleDark ) ),
            UIBarButtonItem( title: "RTL", style: .plain, target: self, action: #selector( toggleDirection ) ),
        ]
        draw( shown )
    }

    // MARK: The list

    public func tableView( _ tableView: UITableView, numberOfRowsInSection section: Int ) -> Int { Shown.allCases.count }

    public func tableView( _ tableView: UITableView, cellForRowAt indexPath: IndexPath ) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell( withIdentifier: "state", for: indexPath )
        var content = cell.defaultContentConfiguration()
        content.text = Shown.allCases[ indexPath.row ].title
        cell.contentConfiguration = content
        cell.accessoryType = .disclosureIndicator
        return cell
    }

    public func tableView( _ tableView: UITableView, didSelectRowAt indexPath: IndexPath ) {
        tableView.deselectRow( at: indexPath, animated: true )
        let page = CallScreenPreview( Shown.allCases[ indexPath.row ] )
        if let navigationController { navigationController.pushViewController( page, animated: true ) } else { present( page, animated: true ) }
    }

    // MARK: One state

    @objc private func toggleDark() {
        dark.toggle()
        applyTraits()
    }

    @objc private func toggleDirection() {
        rightToLeft.toggle()
        applyTraits()
    }

    private func applyTraits() {
        guard let screen else { return }
        let traits = UITraitCollection( traitsFrom: [
            UITraitCollection( userInterfaceStyle: dark ? .dark : .light ),
            UITraitCollection( layoutDirection: rightToLeft ? .rightToLeft : .leftToRight ),
        ] )
        setOverrideTraitCollection( traits, forChild: screen )
        screen.view.semanticContentAttribute = rightToLeft ? .forceRightToLeft : .forceLeftToRight
        screen.view.setNeedsLayout()
    }

    private func draw( _ shown: Shown ) {
        // The screen's look and the app's pieces are installed with the call screen.
        _ = CallScreen.shared
        let screen = BmCallsScreen()
        screen.canShareScreen = false
        addChild( screen )
        screen.view.frame = view.bounds
        screen.view.autoresizingMask = [ .flexibleWidth, .flexibleHeight ]
        view.addSubview( screen.view )
        screen.didMove( toParent: self )
        self.screen = screen
        applyTraits()

        let group = shown == .group || shown == .groupVoice
        let video = shown != .voice && shown != .groupVoice
        screen.show( name: group ? "Daily meeting" : "Ann", avatar: "", video: video )
        screen.apply( state: Self.state( shown ) )
        if group { screen.setRoster( Self.people() ) }
    }

    /// The state as the call screen hands it to the screen in a call (CallScreen.state).
    static func state( _ shown: Shown ) -> [ String: Any ] {
        let phase: String
        switch shown {
        case .calling: phase = "ringing_out"
        case .ringing: phase = "ringing_in"
        case .connecting: phase = "connecting"
        case .peerLost, .reconnecting: phase = "reconnecting"
        default: phase = "in_progress"
        }
        let group = shown == .group || shown == .groupVoice
        let video = shown != .voice && shown != .groupVoice
        let off = shown == .off
        let trouble: Any
        switch shown {
        case .peerLost: trouble = "peer"
        case .reconnecting: trouble = "self"
        default: trouble = NSNull()
        }
        return [
            "phase": phase,
            "trouble": trouble,
            "type": video ? "video" : "audio",
            "group": group,
            "peer": [ "camera": false, "microphone": !off, "screen": false, "known": phase == "in_progress" || phase == "reconnecting" ],
            "local": [ "muted": off, "camera": false, "screen": false, "front": true, "route": "" ],
            "callMode": group ? "participatory" : NSNull(),
            "roomLocked": false,
            "roomMuted": false,
            "canModerate": false,
            "handRaised": false,
            "online": [ Int ](),
            "peerOnline": true,
        ]
    }

    /// A group call's people with no pictures: this side, someone speaking, someone muted, someone else.
    static func people() -> [ BmCallsRoomParticipant ] {
        func person( _ identity: String, _ name: String, local: Bool = false, speaking: Bool = false, muted: Bool = false ) -> BmCallsRoomParticipant {
            BmCallsRoomParticipant(
                identity: identity, name: name, avatar: "", isLocal: local, video: nil, screen: nil,
                speaking: speaking, audioLevel: speaking ? 0.6 : 0, muted: muted, micMuted: false, handRaised: false,
                isPinned: false, canPublish: true, canAdmin: false, mode: "participant", lost: false
            )
        }
        return [
            person( "me", "You", local: true ),
            person( "ann", "Ann", speaking: true ),
            person( "ben", "Ben", muted: true ),
            person( "cara", "Cara" ),
        ]
    }
}
#endif
"""## ),
    ( "LiveStreamScreen.swift", ##"""
import UIKit
import WordPlusRealtime
import WordPlusRealtimeCalls

/**
 A live stream drawn ready for its viewers, as the web player draws it: the picture, Live and how many watch over it, the
 stream's title, the chat with a field to write in, and a heart for reactions, which float up the picture as everyone
 sends them. Optional, as the module is: an app that draws its own uses `LiveStream` and `LiveStreamVideoView` alone.
 The host goes live from the studio on the web, or with the stream's own calls (`preview()`, `goLive()`).

 ```swift
 let stream = try await rt.calls.stream("show:42")
 present(LiveStreamScreen(stream: stream, title: "The new mugs"), animated: true)
 ```

 Closing it leaves the stream (`leavesOnClose`) and dismisses the screen, unless `onClose` does something else.
 */
@MainActor
public final class LiveStreamScreen: UIViewController, UITableViewDataSource, UITextFieldDelegate {
    /// The screen's words and its colour.
    public struct Appearance {
        /// Its strings in the user's language, by key: `live`, `watching` (`%d` the count), `starts_soon`, `ended`,
        /// `say_something`, `send`, `read_only`, `pinned`, `react`, `close`, `not_sent` (`%@` the code). The English is
        /// the default for any left out.
        public var strings: [String: String]
        /// The send button's and the field's colour.
        public var accent: UIColor

        public init(strings: [String: String] = [:], accent: UIColor = UIColor(red: 0.15, green: 0.39, blue: 0.92, alpha: 1)) {
            self.strings = strings
            self.accent = accent
        }
    }

    static let english: [String: String] = [
        "live": "Live",
        "watching": "%d watching",
        "starts_soon": "The stream starts soon",
        "ended": "This stream has ended",
        "say_something": "Say something…",
        "send": "Send",
        "read_only": "Chat is read-only for you",
        "pinned": "Pinned",
        "react": "Send a heart",
        "close": "Close",
        "not_sent": "Not sent (%@)",
    ]

    public let stream: LiveStream
    public let streamTitle: String?
    public var appearance: Appearance {
        didSet { if isViewLoaded { styled() } }
    }
    /// Whether closing the screen leaves the stream (true), or keeps it for the app.
    public var leavesOnClose = true
    /// What closing does, in place of dismissing the screen.
    public var onClose: (() -> Void)?

    let picture = LiveStreamVideoView()
    let note = UILabel()
    let badge = PaddedLabel()
    let viewers = PaddedLabel()
    let close = UIButton(type: .system)
    let titleLabel = UILabel()
    let pinned = PaddedLabel()
    let table = UITableView(frame: .zero, style: .plain)
    let field = UITextField()
    let send = UIButton(type: .system)
    let heart = UIButton(type: .system)
    let failure = UILabel()
    private let floats = UIView()
    private var shown: [LiveStreamMessage] = []
    private var sending = false

    public init(stream: LiveStream, title: String? = nil, appearance: Appearance = Appearance()) {
        self.stream = stream
        self.streamTitle = title
        self.appearance = appearance
        super.init(nibName: nil, bundle: nil)
        modalPresentationStyle = .fullScreen
    }

    required init?(coder: NSCoder) {
        fatalError("init(coder:) is not used")
    }

    func text(_ key: String) -> String {
        appearance.strings[key] ?? Self.english[key] ?? key
    }

    public override func viewDidLoad() {
        super.viewDidLoad()
        view.backgroundColor = .systemBackground
        view.accessibilityIdentifier = "stream-screen"
        build()
        styled()
        picture.show(stream)
        stream.onChange { [weak self] in self?.render() }
        stream.onReactions { [weak self] counts in
            guard let self else { return }
            for emoji in counts.flatMap({ Array(repeating: $0.key, count: $0.value) }).prefix(6) { self.float(emoji) }
        }
        render()
    }

    // MARK: - Building it

    private func build() {
        let stage = UIView()
        stage.backgroundColor = .black
        stage.clipsToBounds = true
        picture.isAccessibilityElement = true
        picture.accessibilityIdentifier = "stream-picture"
        note.textColor = .white
        note.font = .preferredFont(forTextStyle: .headline)
        note.textAlignment = .center
        note.numberOfLines = 0
        note.accessibilityIdentifier = "stream-note"
        badge.backgroundColor = UIColor(red: 0.86, green: 0.15, blue: 0.15, alpha: 1)
        badge.textColor = .white
        badge.font = .systemFont(ofSize: 12, weight: .bold)
        badge.layer.cornerRadius = 4
        badge.clipsToBounds = true
        badge.accessibilityIdentifier = "stream-live"
        viewers.backgroundColor = UIColor.black.withAlphaComponent(0.55)
        viewers.textColor = .white
        viewers.font = .systemFont(ofSize: 12, weight: .semibold)
        viewers.layer.cornerRadius = 4
        viewers.clipsToBounds = true
        viewers.accessibilityIdentifier = "stream-viewers"
        close.setImage(UIImage(systemName: "xmark"), for: .normal)
        close.tintColor = .white
        close.backgroundColor = UIColor.black.withAlphaComponent(0.55)
        close.layer.cornerRadius = 16
        close.accessibilityIdentifier = "stream-close"
        close.addTarget(self, action: #selector(closed), for: .touchUpInside)
        floats.isUserInteractionEnabled = false

        titleLabel.font = .preferredFont(forTextStyle: .headline)
        titleLabel.numberOfLines = 2
        titleLabel.text = streamTitle
        titleLabel.isHidden = streamTitle?.isEmpty ?? true
        pinned.font = .preferredFont(forTextStyle: .subheadline)
        pinned.numberOfLines = 2
        pinned.backgroundColor = .secondarySystemBackground
        pinned.layer.cornerRadius = 8
        pinned.clipsToBounds = true
        pinned.accessibilityIdentifier = "stream-pinned"

        table.dataSource = self
        table.separatorStyle = .none
        table.allowsSelection = false
        table.keyboardDismissMode = .interactive
        table.register(UITableViewCell.self, forCellReuseIdentifier: "message")
        table.rowHeight = UITableView.automaticDimension
        table.estimatedRowHeight = 28
        table.accessibilityIdentifier = "stream-chat"

        field.borderStyle = .roundedRect
        field.returnKeyType = .send
        field.delegate = self
        field.accessibilityIdentifier = "stream-field"
        send.setImage(UIImage(systemName: "paperplane.fill"), for: .normal)
        send.accessibilityIdentifier = "stream-send"
        send.addTarget(self, action: #selector(sent), for: .touchUpInside)
        heart.setImage(UIImage(systemName: "heart.fill"), for: .normal)
        heart.tintColor = UIColor(red: 0.93, green: 0.27, blue: 0.4, alpha: 1)
        heart.accessibilityIdentifier = "stream-react"
        heart.addTarget(self, action: #selector(hearted), for: .touchUpInside)
        failure.font = .preferredFont(forTextStyle: .footnote)
        failure.textColor = .secondaryLabel
        failure.numberOfLines = 0
        failure.isHidden = true
        failure.accessibilityIdentifier = "stream-failure"

        let composer = UIStackView(arrangedSubviews: [field, heart, send])
        composer.spacing = 8
        composer.alignment = .center
        let below = UIStackView(arrangedSubviews: [titleLabel, pinned, table, failure, composer])
        below.axis = .vertical
        below.spacing = 8

        for v in [stage, picture, note, badge, viewers, close, floats, below] as [UIView] { v.translatesAutoresizingMaskIntoConstraints = false }
        stage.addSubview(picture)
        stage.addSubview(note)
        stage.addSubview(floats)
        stage.addSubview(badge)
        stage.addSubview(viewers)
        stage.addSubview(close)
        view.addSubview(stage)
        view.addSubview(below)

        let safe = view.safeAreaLayoutGuide
        let sixteenByNine = stage.heightAnchor.constraint(equalTo: stage.widthAnchor, multiplier: 9 / 16)
        sixteenByNine.priority = .defaultHigh
        NSLayoutConstraint.activate([
            stage.topAnchor.constraint(equalTo: safe.topAnchor),
            stage.leadingAnchor.constraint(equalTo: view.leadingAnchor),
            stage.trailingAnchor.constraint(equalTo: view.trailingAnchor),
            sixteenByNine,
            stage.heightAnchor.constraint(lessThanOrEqualTo: safe.heightAnchor, multiplier: 0.6),
            picture.topAnchor.constraint(equalTo: stage.topAnchor),
            picture.bottomAnchor.constraint(equalTo: stage.bottomAnchor),
            picture.leadingAnchor.constraint(equalTo: stage.leadingAnchor),
            picture.trailingAnchor.constraint(equalTo: stage.trailingAnchor),
            floats.topAnchor.constraint(equalTo: stage.topAnchor),
            floats.bottomAnchor.constraint(equalTo: stage.bottomAnchor),
            floats.leadingAnchor.constraint(equalTo: stage.leadingAnchor),
            floats.trailingAnchor.constraint(equalTo: stage.trailingAnchor),
            note.centerYAnchor.constraint(equalTo: stage.centerYAnchor),
            note.leadingAnchor.constraint(equalTo: stage.leadingAnchor, constant: 24),
            note.trailingAnchor.constraint(equalTo: stage.trailingAnchor, constant: -24),
            badge.topAnchor.constraint(equalTo: stage.topAnchor, constant: 12),
            badge.leadingAnchor.constraint(equalTo: safe.leadingAnchor, constant: 12),
            viewers.centerYAnchor.constraint(equalTo: badge.centerYAnchor),
            viewers.leadingAnchor.constraint(equalTo: badge.trailingAnchor, constant: 6),
            close.topAnchor.constraint(equalTo: stage.topAnchor, constant: 8),
            close.trailingAnchor.constraint(equalTo: safe.trailingAnchor, constant: -8),
            close.widthAnchor.constraint(equalToConstant: 32),
            close.heightAnchor.constraint(equalToConstant: 32),
            below.topAnchor.constraint(equalTo: stage.bottomAnchor, constant: 12),
            below.leadingAnchor.constraint(equalTo: safe.leadingAnchor, constant: 16),
            below.trailingAnchor.constraint(equalTo: safe.trailingAnchor, constant: -16),
            below.bottomAnchor.constraint(equalTo: view.keyboardLayoutGuide.topAnchor, constant: -8),
            send.widthAnchor.constraint(equalToConstant: 36),
            heart.widthAnchor.constraint(equalToConstant: 36),
            field.heightAnchor.constraint(greaterThanOrEqualToConstant: 36),
        ])
    }

    private func styled() {
        badge.text = text("live").uppercased()
        field.placeholder = text("say_something")
        field.tintColor = appearance.accent
        send.tintColor = appearance.accent
        send.accessibilityLabel = text("send")
        heart.accessibilityLabel = text("react")
        close.accessibilityLabel = text("close")
        render()
    }

    // MARK: - Drawing it

    func render() {
        guard isViewLoaded else { return }
        let live = stream.state == .live
        badge.isHidden = !live
        viewers.isHidden = !live
        viewers.text = String(format: text("watching"), stream.viewers)
        switch stream.state {
        case .idle: note.text = text("starts_soon")
        case .ended: note.text = text("ended")
        case .live: note.text = nil
        }
        note.isHidden = note.text == nil
        picture.accessibilityValue = picture.showsPicture ? "picture" : "none"
        heart.isHidden = !(live && stream.reactionsOn)
        let writes = stream.canWrite
        field.isEnabled = writes && !sending
        send.isEnabled = writes && !sending
        field.placeholder = writes ? text("say_something") : text("read_only")
        if let message = stream.pinned {
            pinned.attributedText = line(message, prefix: text("pinned") + ": ")
            pinned.isHidden = false
        } else {
            pinned.isHidden = true
        }
        if stream.messages.map(\.id) != shown.map(\.id) {
            shown = stream.messages
            table.reloadData()
            if !shown.isEmpty { table.scrollToRow(at: IndexPath(row: shown.count - 1, section: 0), at: .bottom, animated: false) }
        }
    }

    private func line(_ message: LiveStreamMessage, prefix: String = "") -> NSAttributedString {
        let body = UIFont.preferredFont(forTextStyle: .subheadline)
        let bold = UIFont.systemFont(ofSize: body.pointSize, weight: .semibold)
        let out = NSMutableAttributedString(string: prefix, attributes: [.font: body, .foregroundColor: UIColor.secondaryLabel])
        out.append(NSAttributedString(string: message.name + "  ", attributes: [.font: bold, .foregroundColor: UIColor.label]))
        out.append(NSAttributedString(string: message.text, attributes: [.font: body, .foregroundColor: UIColor.label]))
        return out
    }

    public func tableView(_ tableView: UITableView, numberOfRowsInSection section: Int) -> Int {
        shown.count
    }

    public func tableView(_ tableView: UITableView, cellForRowAt indexPath: IndexPath) -> UITableViewCell {
        let cell = tableView.dequeueReusableCell(withIdentifier: "message", for: indexPath)
        var content = cell.defaultContentConfiguration()
        content.attributedText = line(shown[indexPath.row])
        content.directionalLayoutMargins = NSDirectionalEdgeInsets(top: 3, leading: 0, bottom: 3, trailing: 0)
        cell.contentConfiguration = content
        // Its text in line with the title, not the table's own margins.
        cell.preservesSuperviewLayoutMargins = false
        cell.directionalLayoutMargins = .zero
        cell.backgroundColor = .clear
        cell.accessibilityIdentifier = "stream-message"
        return cell
    }

    // MARK: - What the person does

    public func textFieldShouldReturn(_ textField: UITextField) -> Bool {
        sent()
        return false
    }

    @objc private func sent() {
        let words = (field.text ?? "").trimmingCharacters(in: .whitespacesAndNewlines)
        guard !words.isEmpty, !sending else { return }
        sending = true
        failure.isHidden = true
        render()
        Task { @MainActor in
            do {
                try await stream.send(words)
                field.text = ""
            } catch {
                failure.text = String(format: text("not_sent"), (error as? CallError)?.code ?? "\(error)")
                failure.isHidden = false
            }
            sending = false
            render()
        }
    }

    @objc private func hearted() {
        stream.react(.heart)
        float(LiveStreamReaction.heart.rawValue)
    }

    @objc func closed() {
        if leavesOnClose { stream.leave() }
        if let onClose { onClose() } else { dismiss(animated: true) }
    }

    /// A reaction floating up the picture, from its lower right: the emoji that was sent.
    private func float(_ emoji: String) {
        guard floats.bounds.height > 0 else { return }
        let image = UILabel()
        image.text = emoji
        image.font = .systemFont(ofSize: 20)
        image.textAlignment = .center
        let x = floats.bounds.width - 36 - CGFloat.random(in: 0...24)
        image.frame = CGRect(x: x, y: floats.bounds.height - 40, width: 24, height: 22)
        floats.addSubview(image)
        UIView.animate(withDuration: 1.8, delay: 0, options: [.curveEaseOut], animations: {
            image.frame.origin.y = self.floats.bounds.height * 0.25
            image.frame.origin.x += CGFloat.random(in: -20...8)
            image.alpha = 0
        }, completion: { _ in image.removeFromSuperview() })
    }
}

/// A label with room around its text, for the badges over the picture.
final class PaddedLabel: UILabel {
    var insets = UIEdgeInsets(top: 3, left: 7, bottom: 3, right: 7)

    override func drawText(in rect: CGRect) {
        super.drawText(in: rect.inset(by: insets))
    }

    override var intrinsicContentSize: CGSize {
        let size = super.intrinsicContentSize
        return CGSize(width: size.width + insets.left + insets.right, height: size.height + insets.top + insets.bottom)
    }
}
"""## ),
    ( "Tests/PiecesTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The call screen's pieces (CallScreen.Pieces), on the real screen with no call:
/// the dock arranged as the app answers, its own button drawn as ours are and hanging up still last, the status line,
/// the view over the stage, and none of it without pieces. Run on a simulator: `xcodebuild test -scheme
/// WordPlusRealtime-Package -destination 'platform=iOS Simulator,name=iPhone 16'`.
@MainActor
final class PiecesTests: XCTestCase {
    override func tearDown() {
        CallScreen.shared.pieces = .init()
        super.tearDown()
    }

    private func screen( phase: String ) -> BmCallsScreen {
        _ = CallScreen.shared
        let screen = BmCallsScreen()
        screen.loadViewIfNeeded()
        screen.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        screen.apply( state: [ "phase": phase, "type": "video", "group": false, "local": [ "muted": false, "camera": false ] ] )
        screen.view.layoutIfNeeded()
        return screen
    }

    /// The dock's buttons, in their order: by what VoiceOver says of them.
    private func dock( _ screen: BmCallsScreen ) -> [ String ] {
        func find( _ view: UIView ) -> UIStackView? {
            if let stack = view as? UIStackView, stack.arrangedSubviews.contains( where: { $0.accessibilityLabel == "End Call" } ) { return stack }
            return view.subviews.lazy.compactMap( find ).first
        }
        return find( screen.view )?.arrangedSubviews.map { $0.accessibilityLabel ?? "?" } ?? []
    }

    private func label( _ screen: BmCallsScreen, _ text: String ) -> UILabel? {
        func find( _ view: UIView ) -> UILabel? {
            if let label = view as? UILabel, label.text == text { return label }
            return view.subviews.lazy.compactMap( find ).first
        }
        return find( screen.view )
    }

    func testWithoutPiecesTheScreenIsOurs() {
        let ours = screen( phase: "ringing_out" )
        XCTAssertEqual( dock( ours ).last, "End Call" )
        XCTAssertFalse( dock( ours ).contains( "Call notes" ) )
        XCTAssertNotNil( label( ours, "Calling…" ) )
    }

    func testTheAppArrangesTheDockAndAddsItsOwnButtonWithHangingUpLast() {
        var pressed = 0
        var phases: [ String ] = []
        CallScreen.shared.pieces = .init( controls: { ours, state in
            phases.append( state.phase )
            // Hanging up put first: it stays last. Picture in picture dropped, the app's button added.
            let end = ours.filter { $0.id == "end" }
            return end + ours.filter { $0.id != "end" && $0.id != "pip" } + [
                .init( id: "notes", label: "Call notes", icon: CallScreen.CallControl.icons[ "alert" ]! ) { pressed += 1 },
            ]
        } )
        let screen = screen( phase: "ringing_out" )
        let row = dock( screen )

        XCTAssertEqual( row.last, "End Call" )
        XCTAssertEqual( row[ row.count - 2 ], "Call notes" )
        XCTAssertFalse( row.contains( "Picture In Picture" ) )
        XCTAssertTrue( phases.contains( "ringing_out" ) )

        // Drawn as ours: a dock button, sized with the rest, and it does what the app said.
        func find( _ view: UIView ) -> UIView? {
            if view.accessibilityIdentifier == "call-control-notes" { return view }
            return view.subviews.lazy.compactMap( find ).first
        }
        let notes = find( screen.view )
        XCTAssertTrue( notes is BmCallsButton )
        XCTAssertGreaterThan( notes?.bounds.width ?? 0, 30 )
        XCTAssertTrue( notes?.accessibilityActivate() ?? false )
        XCTAssertEqual( pressed, 1 )
    }

    func testTheStatusLineAndTheViewOverTheStage() {
        let over = UIView()
        over.accessibilityIdentifier = "my-stage"
        CallScreen.shared.pieces = .init(
            status: { state in state.phase == "ringing_out" ? "Ringing Ann…" : nil },
            stage: { _ in over }
        )
        let ringing = screen( phase: "ringing_out" )
        XCTAssertNotNil( label( ringing, "Ringing Ann…" ) )
        XCTAssertNil( label( ringing, "Calling…" ) )
        XCTAssertTrue( over.superview === ringing.view )

        // A phase the app leaves to us: ours.
        let connecting = screen( phase: "connecting" )
        XCTAssertNotNil( label( connecting, "Connecting..." ) )
    }

    func testAButtonTheAppMakesAnewAtEachChangeKeepsTheDockAsItIsAndDoesTheNewestAction() {
        // As the docs write it: the app's button made in `controls`, so anew at every change of the call, many a second
        // while it connects. The dock keeps the one it shows, with what the newest one says, and isn't built again.
        var made = 0
        var pressed: [ Int ] = []
        CallScreen.shared.pieces = .init( controls: { ours, _ in
            made += 1
            let n = made
            return ours + [ .init( id: "order", label: "Order \( n )", icon: CallScreen.CallControl.icons[ "alert" ]! ) { pressed.append( n ) } ]
        } )
        let screen = screen( phase: "in_progress" )
        func row( _ view: UIView ) -> UIStackView? {
            if let stack = view as? UIStackView, stack.arrangedSubviews.contains( where: { $0.accessibilityLabel == "End Call" } ) { return stack }
            return view.subviews.lazy.compactMap( row ).first
        }
        let before = row( screen.view )?.arrangedSubviews ?? []
        let order = before.first { $0.accessibilityIdentifier == "call-control-order" }
        XCTAssertNotNil( order )

        for _ in 0..<5 {
            screen.apply( state: [ "phase": "in_progress", "type": "video", "group": false, "local": [ "muted": false, "camera": false ] ] )
        }

        XCTAssertGreaterThan( made, 5 )
        XCTAssertEqual( row( screen.view )?.arrangedSubviews ?? [], before )
        XCTAssertEqual( order?.accessibilityLabel, "Order \( made )" )
        XCTAssertTrue( order?.accessibilityActivate() ?? false )
        XCTAssertEqual( pressed, [ made ] )
    }
}
#endif
"""## ),
    ( "Tests/PreviewTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The preview (CallScreenPreview): every state draws the real
/// screen with no call, ringing in offers Answer and Reject, a call offers End Call, a group call has its people, and the
/// list names every state. Run on a simulator, as PiecesTests.
@MainActor
final class PreviewTests: XCTestCase {
    private func labels( _ view: UIView ) -> [ String ] {
        ( view.isHidden ? [] : [ view.accessibilityLabel ].compactMap { $0 } ) + view.subviews.flatMap( labels )
    }

    private func drawn( _ shown: CallScreenPreview.Shown ) -> ( CallScreenPreview, BmCallsScreen ) {
        let preview = CallScreenPreview( shown )
        preview.loadViewIfNeeded()
        preview.view.frame = CGRect( x: 0, y: 0, width: 390, height: 844 )
        preview.view.layoutIfNeeded()
        let screen = preview.children.compactMap { $0 as? BmCallsScreen }.first
        XCTAssertNotNil( screen, "\( shown ) draws the screen" )
        return ( preview, screen! )
    }

    func testEveryStateDrawsTheScreen() {
        for shown in CallScreenPreview.Shown.allCases {
            let ( _, screen ) = drawn( shown )
            let said = labels( screen.view )
            if shown == .ringing {
                XCTAssertTrue( said.contains( "Answer" ), "ringing in offers to answer: \( said )" )
                XCTAssertTrue( said.contains( "Reject" ), "ringing in offers to reject: \( said )" )
            } else if shown == .group || shown == .groupVoice {
                // A group call is left, not ended, and lists its people.
                XCTAssertTrue( said.contains( "Exit Chat" ), "\( shown ) offers Exit Chat: \( said )" )
                XCTAssertTrue( said.contains( "Participants (4)" ), "\( shown ) lists its people: \( said )" )
            } else {
                XCTAssertTrue( said.contains( "End Call" ), "\( shown ) offers End Call: \( said )" )
            }
        }
    }

    func testAGroupCallHasItsPeople() {
        let ( _, screen ) = drawn( .group )
        XCTAssertEqual( screen.roster.map( \.name ), [ "You", "Ann", "Ben", "Cara" ] )
    }

    func testTheListNamesEveryState() {
        let preview = CallScreenPreview()
        preview.loadViewIfNeeded()
        let list = preview.view.subviews.compactMap { $0 as? UITableView }.first
        XCTAssertEqual( list?.numberOfRows( inSection: 0 ), CallScreenPreview.Shown.allCases.count )
    }
}
#endif
"""## ),
    ( "Tests/ThemeTests.swift", ##"""
#if canImport(UIKit)
import UIKit
import XCTest
@testable import WordPlusRealtimeUI

/// The call screen's look from the app's tokens (CallScreen.Appearance, step 1 of customizing): the web's own names
/// for the stage, a grid's tiles, a control and the dock's glass recolour them, and without them the stage stays
/// near-black whatever the palette's other colours. Run on a simulator, as PiecesTests.
@MainActor
final class ThemeTests: XCTestCase {
    override func tearDown() {
        CallScreen.shared.configure( .init() )
        super.tearDown()
    }

    private func rgb( _ color: UIColor ) -> [ Int ] {
        var r: CGFloat = 0, g: CGFloat = 0, b: CGFloat = 0, a: CGFloat = 0
        color.getRed( &r, green: &g, blue: &b, alpha: &a )
        return [ r, g, b ].map { Int( ( $0 * 255 ).rounded() ) }
    }

    func testTheAppsTokensColourTheStageTilesControlsAndDock() {
        CallScreen.shared.configure( .init( tokens: [
            "--bm-call-canvas": "248, 250, 252",
            "--bm-call-tile": "226, 232, 240",
            "--bm-call-btn": "#2563eb",
            "--bm-call-dock": "255, 255, 255",
        ] ) )

        XCTAssertEqual( rgb( BmCallsTheme.stage ), [ 248, 250, 252 ] )
        XCTAssertEqual( rgb( BmCallsTheme.tile ), [ 226, 232, 240 ] )
        XCTAssertEqual( rgb( BmCallsTheme.control ), [ 37, 99, 235 ] )
        XCTAssertEqual( rgb( BmCallsTheme.dockGlass ), [ 255, 255, 255 ] )

        // On the real screen: its ground is the app's stage.
        let preview = CallScreenPreview( .video )
        preview.loadViewIfNeeded()
        let screen = preview.children.compactMap { $0 as? BmCallsScreen }.first
        XCTAssertEqual( screen.flatMap { $0.view.backgroundColor }.map( rgb ), [ 248, 250, 252 ] )
    }

    func testWithoutThemTheStageStaysNearBlack() {
        CallScreen.shared.configure( .init( tokens: [ "--bm-color-accent": "37, 99, 235" ] ) )

        XCTAssertEqual( rgb( BmCallsTheme.stage ), [ 13, 15, 20 ] )
        XCTAssertEqual( rgb( BmCallsTheme.accent ), [ 37, 99, 235 ] )
    }
}
#endif
